slides=[
section(1,'Caderno de estudo','<div class="eyebrow">Anote este caminho</div><h1>Uma dúvida.<br>Uma página.<br><span class="underline blue">Um começo.</span></h1><div class="sticky"><div class="label">Lembrete para hoje</div><p>Você não precisa resolver tudo de uma vez. Encontre o primeiro passo.</p></div>','cover','Abra espaço para aprender →'),
section(2,'Nota 01 / A dúvida','<div class="eyebrow">Escreva onde você travou</div><h2>Deixe a dúvida<br><span class="blue">mais precisa.</span></h2><div class="correction"><div class="scribble crossed">“Não sei nada.”</div><strong>“Não sei como<br>isolar o x.”</strong></div><p class="intro">Foi o enunciado? A fórmula? A conta?<br>Nomear o bloqueio ajuda a escolher<br>o que estudar agora.</p>'),
section(3,'Nota 02 / O plano','<div class="eyebrow">Antes de fazer a conta</div><h2>Organize<br><span class="blue">o raciocínio.</span></h2><ol class="worksheet"><li><b>01</b><div><h3>O que eu tenho?</h3><p>Liste os dados do enunciado.</p></div></li><li><b>02</b><div><h3>O que preciso encontrar?</h3><p>Escreva o objetivo da questão.</p></div></li><li><b>03</b><div><h3>Por onde começo?</h3><p>Escolha um conceito e explique por quê.</p></div></li></ol>'),
section(4,'Nota 03 / A tentativa','<div class="eyebrow">Resolução comentada</div><h2>Cada linha tem<br><span class="blue">um motivo.</span></h2><div class="worked"><div class="row"><span class="formula">2x + 6 = 14</span><span class="annotation">Queremos<br>isolar o x.</span></div><div class="row"><span class="formula">2x = 8</span><span class="annotation">− 6 nos<br>dois lados</span></div><div class="row"><span class="formula mint">x = 4</span><span class="annotation">÷ 2 nos<br>dois lados</span></div></div><p class="exercise">Sem olhar: tente <strong>3x + 6 = 21.</strong></p>','','Confira: x = 5'),
section(5,'Nota 04 / A revisão','<div class="eyebrow">Seu checklist de estudo</div><h2>Antes de virar<br><span class="blue">a página.</span></h2><ul class="squares"><li><span class="square">✓</span>Expliquei o primeiro passo?</li><li><span class="square">✓</span>Fiz uma questão parecida?</li><li><span class="square">✓</span>Conferi minha resposta?</li></ul><div class="sticky"><p>Se uma resposta for “não”, você já sabe onde retomar.</p></div>'),
section(6,'Nota 05 / O Tudy','<div class="eyebrow">Seu caderno encontra a IA</div><h2>Da sua questão<br><span class="blue">à prática.</span></h2><p class="intro">Fotografe a dúvida no Tudy.<br>Entenda os passos e continue estudando.</p>'+phone),
section(7,'Guarde esta página','<div class="eyebrow">Transforme conteúdo em aprendizado</div><h2>Sua próxima<br>descoberta<br><span class="blue">começa aqui.</span></h2><div class="sticky"><p>Entenda. Pratique. Revise.<br>Leve esse método para o seu estudo.</p></div><div class="cta">Conheça o Tudy <span>↗</span></div><p class="small">Link na bio · Salve para consultar depois.</p>','end','@tudy.app')]
