 #ffffff25;padding-top:14px;margin-top:16px;font-size:12px}.result strong{font-size:22px;color:#39D8A5}.review-list{list-style:none;display:grid;gap:12px;margin-top:25px}.review-list li{padding:16px;border-radius:10px;background:#17251F;border:1px solid #28513F;font-size:14px;display:flex;gap:12px}.review-list span{color:#39D8A5}.product{padding:17px;background:#1B202C;border-radius:18px;gap:17px;margin-top:20px}.phone{width:113px;height:176px}.phone:before{left:38px}.phone .formula{padding-top:15px}.product .list{gap:14px}.end h2{font-size:47px}.end .route-map{margin-top:25px}.end .station b{width:40px;height:40px;border-radius:12px;font-size:17px}.end .route-map:before{top:20px}.end .cta{border-radius:10px;margin-top:24px}.end .intro{font-size:13px}@media(max-width:380px){.cover h1{font-size:42px}.end h2{font-size:40px}.product{padding:13px;gap:12px}}
